"""Shared rules assembled in code, not15 separately maintained prompts."""
MASTER_ARCH_LOCK='''使用当前输入的R4 Option A Blender clean clay作为唯一建筑、相机和尺度真值。不得导入R3或旧AI图作为空间源。硬锁墙体边界、房间比例、门洞/窗洞位置与尺度、主要窗框分格、外挑飘窗的平台高度/进深/侧返玻璃、错层、三阶台阶及曲线平台、固定柜体/厨房的拓扑、真实通道与净空。不得扩缩房间、删增门窗、把飘窗变落地窗、抹平台阶、加墙柱门头、虚构新房间或堵塞开口。
同一相机裁切和基础透视保持，3:2画幅1536×1024，自然24–32mm室内视角。浅蓝面为现有玻璃，深灰细框为现有门窗框，不得当实墙；白色顶面不是露天或拆顶，最终呈现正常简洁室内平顶，不新增天窗、复杂吊顶或夸张灯槽。参考里完全未见的房间与窗不能凭空带入镜头。
当前R4次主卧有东西向普通门，向南内开，绝非无门通道，旧斜门仍停用。若参考视角可见，保留直门和门框；若被实墙遮挡，不把门搬到前景，尤其不在前景墙上画新门把手。门口地面连续同标高，不能生成三角台阶。
可变的是活动家具和软装，按本次方向的自由度执行；固定柜和建筑不自由。保持实际尺度、家庭座位能力、原功能区、通道和台阶净空。不要用夸张广角、缩小家具、挪相机或改变建筑来实现方案。
'''
MASTER_STYLE_DNA='''主题为专业住宅室内设计提案和家居杂志摄影，浅自然白蜡木、暖白墙、米白/燕麦/米灰织物、少量克制暖浅石材和极少量深灰/柔和金属。明亮清爽、自然日间采光、真实木纹和织物、精心挑选家具、前中后景层次和住宅生活感。温暖但不橙黄，不过曝，不用巨型黑面、重石材或杂乱陈设。不要奢华酒店、样板房、网红奶油风、重侘寂、暗黑豪宅、塑料CGI或白模简单上色。外景柔和中性，不生成强势城市背景抢空间主体。无文字标识水印。
这是一套候选图库，尚非同一套最终家具的多视角一致性渲染：各机位允许提不同家具灵感，不能为跨视角一致压制design/creative。不要自动选winner。
'''
CAMERA_PROMPTS={
 'A1':'''主视角：展示主会客区、北侧大窗与外挑飘窗和日光。FAITHFUL保留原两组主要座位。DESIGNER保留会客功能但自由替换造型。CREATIVE不要强制原两张沙发，可改为主沙发加两张阅读/休闲椅，合理座位能力和原通道必须成立。media墙/卧室门和错层不在本画面，不额外造出来。''',
 'A2':'''从北侧窗边反看室内、原低media柜侧和公共区错层。北窗在相机背后，前方不能新增大窗。特别注意：本客厅不是传统大电视核心，绝对不自动画巨型黑电视或黑背景墙。保留固定低media柜位置尺寸拓扑，可用暖白克制投影墙/隐藏投影逻辑、轻艺术结合media或低柜功能，不把黑屏变视觉核心。后方门是R4直木门，不能删除或画成挂画。保留三阶、曲线平台和右侧现有玻璃开口。''',
 'A3':'''会客区近景，按当前裁切展示座位、茶几、地毯、木框、织物、边几和灯，家具材质设计最清楚。不要换镜头，不为拍全家具把它缩小或改裁切，不把窗外/画面外的新门搬来。Creative可以在原窗前座位功能区露出阅读椅的一角，而不是必须原双人沙发。''',
 'A4':'''公共区联动是建筑高风险视角：必须保留输入的开放通道、三阶台阶、错层高差、曲线平台轮廓、上下地坪、餐区玻璃开口及真实关系。不要把全屋铺平、不改台阶数、不加隔墙、不恢复斜门。现直门在画面左后被前景墙挡住，不能为了展示门在前景墙上加门把手/门缝。左侧media墙只做克制暖白投影/艺术整合，不生成巨型黑电视墙。活动家具可以按方向改变，但不能堵台阶和公共区通路。''',
 'A5':'''飘窗氛围，参考锁定每根窗框、玻璃分格、低平台的高度/进深/外挑、遮挡关系和通道。Faithful保留当前窗前双人座位一角；Designer改造活动座位造型。Creative允许把窗前活动沙发换为轻量阅读椅/一张较小休闲椅，保留原窗台，不将低平台抬成坐高台/高柜，不新建窗边固定柜。窗台上仅可放薄可撤软垫和少量植物，不能覆盖窗框或加深平台。''',
}
VARIANT_PROMPTS={
 'faithful':'''FAITHFUL REFINEMENT：把现有R4方案做到最好看。保留现有主要座位数量、位置、尺度、朝向和会客组合，保持中央矩形茶几/低media柜的原逻辑。家具外形只作中等成熟化，以燕麦亚麻沙发、浅白蜡木矩形双层茶几和原边柜为主要基准。优化布艺、木色、自然矩形地毯、轻帘、少量台/落地灯、挂画、植物和细节。不要换一种会客布局，不增加座位数量，也不要大黑屏。''',
 'designer':'''DESIGNER REDESIGN：专业设计师设计同一个真实客厅。仅硬锁建筑、固定柜、通道、功能区和合理座位能力；活动家具造型并非真值。请在本机位提供明确可见的再设计：裸露白蜡木平台框沙发、薄直木扶手与厚实米灰软包；中央改为单张低有机椭圆暖浅石材茶几/雕塑木底座，放在原中央会客区；原边几活动家具改为简洁圆柱/精细木架边几（固定柜不改）；用大尺度圆角或椭圆平织地毯、轻薄层次窗帘/低调卷帘、精细线形立灯/圆盘台灯和成熟的大幅艺术组合形成完整层次。若机位看不全这些，至少在可见的座位形态、桌类型、地毯轮廓、材料混搭等四类清楚区别于faithful。新家具尺度可信，不是靠换抱枕出方案，不牺牲通道。''',
 'creative':'''CREATIVE CHALLENGE：给出业主未想到但真实合理的家具方案。建筑/门窗/平台/台阶/固定柜/通道/机位仍绝对锁定，活动家具可重新组合。主动取消原窗前双人沙发，用两张较轻的白蜡木开放圆框阅读/休闲椅取代该座位区（A5可只见一张），主沙发保留在左侧功能区但改成更低的圆润模块式浅木框燕麦座位；不新增L形巨沙发、不把椅子堵在楼梯/门口。原中央长方茶几改为一大一小的有机圆角/圆形嵌套木桌系统，尺度仍与会客区适配。用有机曲线天然纤维地毯、温润轻木与少量浅石混搭、一盏有辨识度的纤细弧形阅读灯+低眩光台灯的分层照明，以及一幅低饱和大幅织物/抽象艺术建立新的焦点（不加厚重背景墙）。窗帘采用透光自然织物的不同处理，少量精挑植物，可增减1–2件非固定家具。体现阅读/会客多功能家庭感，不拥挤、不奢华、不用巨黑电视，不牺牲实际动线。''',
}
DIVERGENCE_REQUIREMENTS={
 'faithful':'差异定位：作为当前R4会客组合的设计基准，不模仿designer/creative的新家具组合。家具与建筑清楚可核对，视觉专业而非白模上色。',
 'designer':'强制差异门槛：相比FAITHFUL至少4类明显改变。优先让1沙发裸露木框与扶手轮廓、2茶几椭圆石面类型、3圆角/椭圆地毯轮廓、4灯具构造与照明层级、5软硬材料混搭、6边家具形态在当前机位实际可见。不能用抱枕/植物/小画代替四类变化；结构造型差异一眼可辨。',
 'creative':'强制差异门槛：相比FAITHFUL至少6类明显改变，而且必须包括1座位组合、2家具轮廓、3照明策略、4焦点/艺术策略，再加5嵌套茶几、6地毯几何、7帘处理/8家具材料混搭。必须真的减少原窗前沙发并出现轻量阅读/休闲椅，不是原两张沙发换衣服。至少体现新的灯具/光层和可见大幅艺术焦点。如果当前机位墙面不在镜头，焦点以阅读角的大灯具和木椅构图表达，而不另造墙。遵守裁切，图里仍是同一真实空间。',
}
def assemble(camera,variant,retry=None):
 parts=[('MASTER_ARCH_LOCK',MASTER_ARCH_LOCK),('MASTER_STYLE_DNA',MASTER_STYLE_DNA),('CAMERA_PROMPT',CAMERA_PROMPTS[camera]),('VARIANT_PROMPT',VARIANT_PROMPTS[variant]),('DIVERGENCE_REQUIREMENT',DIVERGENCE_REQUIREMENTS[variant])]
 text='\n\n'.join('['+n+']\n'+p for n,p in parts)+'\n\n只输出当前机位和方向的一张3:2专业住宅图，不要拼图或写文字。'
 if retry:text+='\n\n[ONE_REVIEW_RETRY]\n'+retry
 return text
